START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM inventory."__EFMigrationsHistory" WHERE "MigrationId" = '20261031184320_MoveFgsVehicleFromSetup') THEN
    CREATE TABLE inventory."FgsVehicle" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "InventoryLocationId" bigint NOT NULL,
        "OwnershipType" character varying(20) NOT NULL DEFAULT 'Owned',
        "OwnershipCompany" character varying(200),
        "Year" smallint,
        "Make" character varying(100),
        "Model" character varying(100),
        "Color" character varying(50),
        "VIN" character varying(50) NOT NULL,
        "LicensePlate" character varying(50),
        "LicensePlateState" character varying(50),
        "PurchaseDate" date,
        "PurchasePrice" numeric(18,2),
        "PurchasedFrom" character varying(200),
        "IsPurchasedNew" boolean,
        "Notes" text,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        CONSTRAINT "PK_FgsVehicle" PRIMARY KEY ("Id"),
        CONSTRAINT "UQ_FgsVehicle_InventoryLocationId" UNIQUE ("InventoryLocationId"),
        CONSTRAINT "CK_FgsVehicle_OwnershipType" CHECK ("OwnershipType" IN ('Owned', 'Leased', 'Rented')),
        CONSTRAINT "FK_FgsVehicle_FgsInventoryLocation_InventoryLocationId" FOREIGN KEY ("InventoryLocationId") REFERENCES inventory."FgsInventoryLocation" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsVehicle_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES inventory."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT
    );
    COMMENT ON TABLE inventory."FgsVehicle" IS 'Stores company-owned or leased vehicles used for field service operations. Each vehicle is associated with an inventory location that serves as a truck storage location.';
    COMMENT ON COLUMN inventory."FgsVehicle"."Id" IS 'Primary key.';
    COMMENT ON COLUMN inventory."FgsVehicle"."TenantId" IS 'Tenant identifier.';
    COMMENT ON COLUMN inventory."FgsVehicle"."CompanyId" IS 'Company identifier.';
    COMMENT ON COLUMN inventory."FgsVehicle"."InventoryLocationId" IS 'Associated truck inventory location.';
    COMMENT ON COLUMN inventory."FgsVehicle"."OwnershipType" IS 'Indicates whether the vehicle is owned, leased, or rented.';
    COMMENT ON COLUMN inventory."FgsVehicle"."OwnershipCompany" IS 'Name of the leasing company, rental provider, or other organization that owns the vehicle when it is not company-owned.';
    COMMENT ON COLUMN inventory."FgsVehicle"."Year" IS 'Vehicle model year.';
    COMMENT ON COLUMN inventory."FgsVehicle"."Make" IS 'Vehicle manufacturer such as Ford, Chevrolet, GMC, Ram, Toyota, etc.';
    COMMENT ON COLUMN inventory."FgsVehicle"."Model" IS 'Vehicle model such as F-150, Transit, Silverado, Express, etc.';
    COMMENT ON COLUMN inventory."FgsVehicle"."Color" IS 'Vehicle exterior color.';
    COMMENT ON COLUMN inventory."FgsVehicle"."VIN" IS 'Vehicle Identification Number assigned by the manufacturer.';
    COMMENT ON COLUMN inventory."FgsVehicle"."LicensePlate" IS 'Vehicle registration plate number.';
    COMMENT ON COLUMN inventory."FgsVehicle"."LicensePlateState" IS 'State or province issuing the vehicle registration.';
    COMMENT ON COLUMN inventory."FgsVehicle"."PurchaseDate" IS 'Date the vehicle was purchased or acquired.';
    COMMENT ON COLUMN inventory."FgsVehicle"."PurchasePrice" IS 'Amount paid to acquire the vehicle.';
    COMMENT ON COLUMN inventory."FgsVehicle"."PurchasedFrom" IS 'Name of the dealership, seller, auction, fleet provider, or other source from which the vehicle was acquired.';
    COMMENT ON COLUMN inventory."FgsVehicle"."IsPurchasedNew" IS 'Indicates whether the vehicle was purchased new or used.';
    COMMENT ON COLUMN inventory."FgsVehicle"."Notes" IS 'Internal notes and remarks regarding the vehicle.';
    COMMENT ON COLUMN inventory."FgsVehicle"."CreatedOn" IS 'Date and time the record was created.';
    COMMENT ON COLUMN inventory."FgsVehicle"."CreatedBy" IS 'User who created the record.';
    COMMENT ON COLUMN inventory."FgsVehicle"."UpdatedOn" IS 'Date and time the record was last updated.';
    COMMENT ON COLUMN inventory."FgsVehicle"."UpdatedBy" IS 'User who last updated the record.';
    COMMENT ON COLUMN inventory."FgsVehicle"."IsActive" IS 'Indicates whether the vehicle is active and available for service operations.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM inventory."__EFMigrationsHistory" WHERE "MigrationId" = '20261031184320_MoveFgsVehicleFromSetup') THEN
    CREATE TABLE inventory."FgsVehicleMaintenance" (
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "VehicleId" bigint NOT NULL,
        "VehicleMaintenanceTypeId" integer NOT NULL,
        "ServiceDate" date NOT NULL,
        "MileageAtService" integer,
        "ServiceProvider" character varying(200),
        "InvoiceNumber" character varying(100),
        "Cost" numeric(18,2),
        "NextServiceDate" date,
        "NextServiceMileage" integer,
        "IsCompleted" boolean NOT NULL DEFAULT TRUE,
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        "Description" character varying(500),
        "Notes" text,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        CONSTRAINT "PK_FgsVehicleMaintenance" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_FgsVehicleMaintenance_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES inventory."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsVehicleMaintenance_FgsVehicle_VehicleId" FOREIGN KEY ("VehicleId") REFERENCES inventory."FgsVehicle" ("Id") ON DELETE RESTRICT
    );
    COMMENT ON TABLE inventory."FgsVehicleMaintenance" IS 'Stores completed and scheduled maintenance activities, inspections, repairs, and service history for company vehicles.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."TenantId" IS 'Tenant identifier.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."CompanyId" IS 'Company identifier.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."Id" IS 'Primary key.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."VehicleId" IS 'Vehicle that received or is scheduled to receive maintenance service.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."VehicleMaintenanceTypeId" IS 'Type of maintenance activity being performed or scheduled. References glo.GloVehicleMaintenanceType as scalar only.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."ServiceDate" IS 'Date the maintenance was performed or is scheduled to be performed.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."MileageAtService" IS 'Vehicle odometer reading at the time the maintenance was performed.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."ServiceProvider" IS 'Name of the repair shop, dealership, service provider, or maintenance vendor.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."InvoiceNumber" IS 'Vendor invoice, receipt, repair order, or work order number associated with the maintenance activity.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."Cost" IS 'Total cost incurred for the maintenance activity.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."NextServiceDate" IS 'Recommended next service date based on maintenance provider recommendations.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."NextServiceMileage" IS 'Recommended next service mileage based on maintenance provider recommendations.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."IsCompleted" IS 'Indicates whether the maintenance activity has been completed. False indicates a scheduled or pending maintenance item.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."IsActive" IS 'Indicates whether the maintenance record is active and available for use.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."Description" IS 'Short summary of the maintenance activity performed or scheduled.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."Notes" IS 'Detailed notes, observations, recommendations, or repair information related to the maintenance activity.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."CreatedOn" IS 'Date and time the record was created.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."CreatedBy" IS 'User who created the record.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."UpdatedOn" IS 'Date and time the record was last updated.';
    COMMENT ON COLUMN inventory."FgsVehicleMaintenance"."UpdatedBy" IS 'User who last updated the record.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM inventory."__EFMigrationsHistory" WHERE "MigrationId" = '20261031184320_MoveFgsVehicleFromSetup') THEN
